  const endpointByPage = { people: '/users', departments: '/departments', teams: '/teams', projects: '/projects', clients: '/clients', tasks: '/tasks', tickets: '/support-tickets' };
  const inputs = page === 'departments' ? { name: form.name } : page === 'teams' ? { name: form.name, departmentId: Number(form.departmentId) } : page === 'people' ? { employeeId: form.employeeId, name: form.name, email: form.email, password: form.password, roleId: Number(form.roleId), teamId: form.teamId ? Number(form.teamId) : null, departmentId: form.departmentId ? Number(form.departmentId) : null } : page === 'projects' ? { name: form.name, clientName: form.clientName, description: form.description, startDate: form.startDate, deadline: form.deadline, priority: form.priority, status: form.status, departmentId: Number(form.departmentId) } : page === 'clients' ? { name: form.name, contactPerson: form.contactPerson, email: form.email, phone: form.phone || null } : page === 'tickets' ? { title: form.title, description: form.description, clientId: Number(form.clientId), priority: form.priority, projectId: form.projectId ? Number(form.projectId) : null } : { title: form.title, description: form.description, status: form.status, deadline: form.deadline, projectId: Number(form.projectId), userId: Number(form.userId) };
